    # Validate hour value
    try:
        hour = int(hour_str)
    except ValueError:
        raise ValueError("Hour must be an integer")

    if hour < 1 or hour > 12:
        raise ValueError("Hour must be between 1 and 12")

    # Validate minute value
    try:
        minute = int(minute_str)
    except ValueError:
        raise ValueError("Minutes must be an integer")

    if minute < 0 or minute > 59:
        raise ValueError("Minutes must be between 00 and 59")

    # Validate suffix
    if suffix not in ("AM", "PM", "am", "pm", "A.M.", "P.M.", "a.m.", "p.m."):
        raise ValueError("Unknown suffix")

    # Convert to 24-hour format
    suffix_upper = suffix.upper()
    if suffix_upper == "AM":
        if hour == 12:
            hour = 0
    elif suffix_upper == "PM":
        if hour != 12:
            hour += 12

    return f"{hour:02d}:{minute:02d}"
